#!/usr/bin/env bash
# generate_examples.sh — build fig:qual_line_tracing panels + a provenance manifest.
#
# Consumes the protocol-selected pair (pairs.json) and the evaluation predictions
# already generated by 06_evaluate.sh (neither is re-generated here — the pair is
# frozen and must not be re-selected per sample). For each exemplar it composes a
# four-panel strip (input / reference / vanilla / selfcond) at the native
# 3216x80 geometry, records per-sample LCP for both methods, and writes
# examples/manifest.json. The paper's three historical cherry-pick IDs are
# recorded as `source_missing`: their original predictions/scores/checkpoints are
# not reproduced from those IDs, and no similar-looking sample is substituted.
set -euo pipefail

SELF_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
_d="$SELF_DIR"; while [[ "$_d" != "${_d%/*}" ]]; do
  [[ -f "$_d/scripts/common/env.sh" ]] && { COMMON="$_d/scripts/common"; break; }
  _d="${_d%/*}"
done
# shellcheck disable=SC1090
source "$COMMON/env.sh"
CONFIG="${CONFIG_OVERRIDE:-$SELF_DIR/config.yaml}"
CFG() { python "$COMMON/read_config.py" "$CONFIG" "$1" "${2:-}"; }

DATA_ROOT="$(resolve_path "$(CFG data.data_root)")"
VAL_METADATA="$DATA_ROOT/val/metadata.csv"
PAIR="$(resolve_path "$(CFG outputs.pair_manifest)")"
EVAL_ROOT="$(resolve_path "$(CFG outputs.eval_root)")"
EXAMPLES_DIR="$(dirname "$(resolve_path "$(CFG outputs.eval_root)")")/examples"

export PYTHONPATH="${REPO_ROOT}/src:${PYTHONPATH:-}"

python - "$VAL_METADATA" "$DATA_ROOT" "$PAIR" "$EVAL_ROOT" "$EXAMPLES_DIR" "$CONFIG" <<'PY'
import json, sys
from argparse import Namespace
from pathlib import Path

metadata_csv = Path(sys.argv[1]); data_root = Path(sys.argv[2])
pair_path = Path(sys.argv[3]); eval_root = Path(sys.argv[4])
out_dir = Path(sys.argv[5]); config_path = Path(sys.argv[6])

import yaml
cfg = yaml.safe_load(open(config_path, encoding="utf-8"))
historical_ids = cfg.get("examples", {}).get("ids", [])
selection_reason = cfg.get("examples", {}).get("selection_reason", "")

from PIL import Image
from a5_line_trace_image_dataset.eval import load_rows, score_sample, ShardReader

pair = json.loads(pair_path.read_text(encoding="utf-8"))
rows = load_rows(str(metadata_csv))
reader = ShardReader(data_root)

manifest = {
    "task": "line_tracing",
    "pair": pair,
    "selection_reason": selection_reason,
    "historical_ids": historical_ids,
    "source_missing": list(historical_ids),   # no original predictions/scores/checkpoints recovered
    "examples": [],
}

def pred_file(method, idx):
    # evaluation.py names predictions `{row_pos:05d}_{sanitized}.png`.
    matches = sorted((eval_root / method / "predictions").glob(f"{idx:05d}_*.png"))
    return matches[0] if matches else None

def lcp_for(method, row, idx):
    p = pred_file(method, idx)
    if p is None:
        return None
    img = Image.open(p).convert("RGB")
    s = score_sample(row, img, Namespace(strict_size=True))
    return s["max_correct_prefix_steps"]

def load_shard(row, key):
    url = row["image"] if key == "outputs" else row["edit_image"]
    return reader.load_image(url, key)

# Pick exemplars from the current eval split: "selfcond correct & vanilla wrong".
out_dir.mkdir(parents=True, exist_ok=True)
candidates = []
for idx, row in enumerate(rows):
    v = lcp_for("vanilla", row, idx)
    s = lcp_for("selfcond", row, idx)
    if v is None or s is None:
        continue
    max_steps = int(row.get("num_permutations", 50))
    candidates.append((idx, row, v, s, s == max_steps and v < max_steps))

preferred = [c for c in candidates if c[4]]
chosen = (preferred or candidates)[:3]

for idx, row, v, s, _ in chosen:
    panel = Image.new("RGB", (int(row["image_width"]), int(row["image_height"]) * 4), "white")
    panel.paste(load_shard(row, "inputs").convert("RGB"), (0, 0))
    panel.paste(load_shard(row, "outputs").convert("RGB"), (0, int(row["image_height"])))
    panel.paste(Image.open(pred_file("vanilla", idx)), (0, int(row["image_height"]) * 2))
    panel.paste(Image.open(pred_file("selfcond", idx)), (0, int(row["image_height"]) * 3))
    panel.save(out_dir / f"{idx:06d}_panel.png")
    manifest["examples"].append({
        "id": f"{idx:05d}_shard:000000:{idx}",
        "index": idx,
        "panel": f"examples/{idx:06d}_panel.png",
        "vanilla_lcp": v,
        "selfcond_lcp": s,
        "vanilla_wrong_selfcond_correct": bool(s == int(row.get("num_permutations", 20)) and v < int(row.get("num_permutations", 20))),
    })

(out_dir / "manifest.json").write_text(json.dumps(manifest, indent=2), encoding="utf-8")
print(json.dumps(manifest, indent=2))
if not manifest["examples"] and manifest["source_missing"]:
    print("[generate_examples] no reproducible panels; historical IDs marked source_missing", file=sys.stderr)
PY

echo "[generate_examples] done -> $EXAMPLES_DIR"